import { requestUrl } from "obsidian";
import { logger } from "@/utils/logger";
import { withTimeout } from "@/dictionary/helpers";

// 内存 LRU 缓存（不再使用 localStorage，避免明文存储敏感数据）
class MemoryLRUCache<V> {
    private cache = new Map<string, V>();
    private maxSize: number;

    constructor(maxSize: number = 200) {
        this.maxSize = maxSize;
    }

    get(key: string): V | undefined {
        if (!this.cache.has(key)) return undefined;
        // LRU: 移到末尾
        const value = this.cache.get(key)!;
        this.cache.delete(key);
        this.cache.set(key, value);
        return value;
    }

    set(key: string, value: V): void {
        if (this.cache.has(key)) {
            this.cache.delete(key);
        }
        if (this.cache.size >= this.maxSize) {
            const firstKey = this.cache.keys().next().value;
            this.cache.delete(firstKey);
        }
        this.cache.set(key, value);
    }

    clear(): void {
        this.cache.clear();
    }
}

// 全局内存缓存实例
const queryCache = new MemoryLRUCache<any>(200);

// 辅助函数：延迟
function sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
}

// 判断是否可重试的状态码
function isRetryableStatus(status: number): boolean {
    return [408, 409, 425, 429, 500, 502, 503, 504].includes(status);
}

// 格式化错误信息
function formatAIError(status: number, responseText?: string): string {
    const trimmed = (responseText || '').trim();
    if (status === 401) return '❌ API Key 无效或未设置 (401)';
    if (status === 403) return '❌ API Key 没有权限或账户受限 (403)';
    if (status === 404) return '❌ API 端点不存在，请检查 API URL (404)';
    if (status === 408) return `⏱️ 请求超时 (408)，请检查网络${trimmed ? `\n${trimmed}` : ''}`;
    if (status === 429) return `🚦 请求过于频繁 (429)，请稍后重试${trimmed ? `\n${trimmed}` : ''}`;
    if (status >= 500 && status <= 599) return `⚠️ 服务端错误 (${status})，请稍后重试${trimmed ? `\n${trimmed}` : ''}`;
    return `AI API 错误 (${status})${trimmed ? `: ${trimmed}` : ''}`;
}

export async function search(text: string, settings: any) {
    const ai = settings?.ai || {};
    const { api_key, api_url, model, prompt } = ai;

    if (!api_key) throw new Error("❌ 请在设置中配置 API Key");
    if (!api_url) throw new Error('❌ 请在设置中配置 API URL');

    // Include provider/endpoint in the key so changing providers never shows
    // a response generated by a previous backend.
    const cacheKey = JSON.stringify({
        text,
        provider: ai.provider || "custom",
        api_url,
        model,
        prompt,
    });
    const cached = queryCache.get(cacheKey);
    if (cached) {
        logger.debug(`AI Query cache hit for: ${text}`);
        return cached;
    }

    // Enforce HTTPS for security, allow HTTP only for local development
    const isLocalDev = api_url.startsWith('http://localhost') || api_url.startsWith('http://127.0.0.1');
    if (!api_url.startsWith('https://') && !isLocalDev) {
        throw new Error('API URL must use https:// for security. Only http://localhost and http://127.0.0.1 are allowed for local development.');
    }

    // 构建请求体（适配 OpenAI 格式）
    const body = {
        model: model,
        messages: [
            { role: "system", content: prompt },
            { role: "user", content: text }
        ],
        max_tokens: 200,
        temperature: 0.3
    };

    // 重试机制
    const maxRetries = 3;
    let lastStatus: number | null = null;
    let lastText: string | undefined;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
        if (attempt > 0) {
            const delayMs = Math.min(15000, 1000 * Math.pow(2, attempt - 1));
            logger.debug(`AI 请求重试 ${attempt}/${maxRetries}，等待 ${delayMs}ms...`);
            await sleep(delayMs);
        }

        try {
            const response = await withTimeout(requestUrl({
                url: api_url,
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "Authorization": `Bearer ${api_key}`
                },
                body: JSON.stringify(body),
                throw: false
            }), 20000);

            if (response.status >= 200 && response.status < 300) {
                // 缓存结果
                queryCache.set(cacheKey, response.json);
                return response.json;
            }

            lastStatus = response.status;
            lastText = response.text;

            // 判断是否可重试
            const shouldRetry = isRetryableStatus(response.status) && attempt < maxRetries;
            if (!shouldRetry) {
                throw new Error(formatAIError(response.status, response.text));
            }
        } catch (e: any) {
            // 网络错误等
            if (e.message && !e.message.includes('API')) {
                lastText = e.message;
                if (attempt >= maxRetries) {
                    throw new Error(`⏱️ 网络请求失败: ${e.message}`);
                }
            } else {
                throw e;
            }
        }
    }

    throw new Error(formatAIError(lastStatus ?? 0, lastText));
}

// 增加翻译功能供例句使用
export async function translate(text: string, settings: any) {
    const { api_key, api_url, model, trans_prompt = "Translate: {sentence}" } = settings?.ai || {};
    if (!api_key) throw new Error("❌ 请在设置中配置 API Key");
    if (!api_url) throw new Error('❌ 请在设置中配置 API URL');
    // Enforce HTTPS for security, allow HTTP only for local development
    const isLocalDev = api_url.startsWith('http://localhost') || api_url.startsWith('http://127.0.0.1');
    if (!api_url.startsWith('https://') && !isLocalDev) {
        throw new Error('API URL must use https:// for security. Only http://localhost and http://127.0.0.1 are allowed for local development.');
    }

    // 替换占位符
    const finalPrompt = trans_prompt.replace("{sentence}", text);

    const body = {
        model: model,
        messages: [
            { role: "user", content: finalPrompt }
        ],
        max_tokens: 150,
        temperature: 0.3
    };

    // 重试机制
    const maxRetries = 3;
    let lastStatus: number | null = null;
    let lastText: string | undefined;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
        if (attempt > 0) {
            const delayMs = Math.min(15000, 1000 * Math.pow(2, attempt - 1));
            await sleep(delayMs);
        }

        try {
            const response = await withTimeout(requestUrl({
                url: api_url,
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    "Authorization": `Bearer ${api_key}`
                },
                body: JSON.stringify(body),
                throw: false
            }), 20000);

            if (response.status >= 200 && response.status < 300) {
                const content = response.json?.choices?.[0]?.message?.content;
                if (typeof content !== "string" || !content.trim()) {
                    throw new Error("AI translation returned no content");
                }
                return content.trim();
            }

            lastStatus = response.status;
            lastText = response.text;

            const shouldRetry = isRetryableStatus(response.status) && attempt < maxRetries;
            if (!shouldRetry) {
                throw new Error(formatAIError(response.status, response.text));
            }
        } catch (e: any) {
            if (e.message && !e.message.includes('API')) {
                lastText = e.message;
                if (attempt >= maxRetries) {
                    throw new Error(`⏱️ 翻译请求失败: ${e.message}`);
                }
            } else {
                throw e;
            }
        }
    }

    throw new Error(formatAIError(lastStatus ?? 0, lastText));
}
